from pathlib import Path
import base64
root=Path(__file__).parent

def img(name):
    return 'data:image/png;base64,'+base64.b64encode((root/'assets'/name).read_bytes()).decode()
def shot(name, cls='', style=''):
    return f'<img class="shot {cls}" style="{style}" src="{img(name)}" alt="Actual Bizroam application — {name.replace(".png", "").replace("-", " ")}">'
font=base64.b64encode(Path('/usr/share/fonts/truetype/freefont/FreeSans.ttf').read_bytes()).decode()
fontbold=base64.b64encode(Path('/usr/share/fonts/truetype/freefont/FreeSansBold.ttf').read_bytes()).decode()
slides=[]
def slide(content,cls=''):
    n=len(slides)+1
    slides.append(f'<section class="slide {cls}" aria-label="Slide {n}"><div class="topline"><span class="brand">bizroam ↗</span><span>FROM CURIOSITY TO DISCOVERY</span></div>{content}<footer><span>BIZROAM · SAN FRANCISCO</span><span>{n:02d} / 05</span></footer></section>')
slide(f'''<div class="hero-copy"><div class="eyebrow">TWO FRENCH PEOPLE. ONE UNFAMILIAR CITY.</div><h1>Great companies.<br>Right around<br><em>your corner.</em></h1><p class="lead">We came to SF surrounded by startups and big tech.<br>But who’s here? What do they build? How big are they?</p><div class="hero-bottom"><span class="pill">MEET BIZROAM</span><span>Your personal AI company guide.</span></div></div><div class="phone hero-phone">{shot('mobile-map.png')}</div><span class="image-note hero-note">ACTUAL APP · SAVED SF WALK · MAP © OPENSTREETMAP</span>''','cover dark')
slide(f'''<div class="eyebrow">01 — YOUR INTERESTS. YOUR NEIGHBORHOOD.</div><h2>Turn a walk into<br><em>a personal discovery.</em></h2><div class="map-copy"><p>Choose your interests.<br>Start walking.<br>Let your guide explore.</p><div class="mini-tags"><span>Tech startups</span><span>Major tech companies</span><small>Editable tags + free text</small></div><div class="map-metric"><strong>500 m</strong><span>discovery radius</span></div><p class="map-detail">Names on the map.<br>Circles reflect company value.*<br>Cards arrive progressively.</p><p class="tiny">* Dated valuation, market cap or acquisition value.<br>Unknown: N/A. Logarithmic circle scale.</p></div><div class="desktop-shot">{shot('desktop-discoveries.png')}</div><span class="image-note map-note">ACTUAL APP · SAVED SF SESSION · MAP © OPENSTREETMAP CONTRIBUTORS</span>''','dark map-slide five-map')
slide(f'''<div class="eyebrow">02 — UNDERSTAND IT NOW. REMEMBER IT LATER.</div><div class="feature-copy"><h2>Behind every pin,<br><em>a useful story.</em></h2><div class="feature-bits"><div><b>Company profiles</b><p>What they build, why they fit,<br>address checks and openable sources.</p></div><div><b>Your passed-by trail</b><p>Within 100 m: saved automatically.<br>Chronological. No duplicate places.</p></div><div><b>Keep your discoveries</b><p>History and preferences in your browser.<br>No account. Alerts inside the app.</p></div></div><div class="small-proof">Nylas: <strong>linked research sources</strong><br>+ public Hacker News discussions.</div></div><div class="feature-profile">{shot('profile-nylas.png')}</div><div class="feature-history phone">{shot('mobile-history.png')}</div><span class="image-note feature-note">ACTUAL APP · NYLAS PROFILE / ZENDESK TRAIL · MAP © OPENSTREETMAP</span>''','light five-features')
slide('''<div class="eyebrow">03 — AN AGENT THAT DOES THE LEGWORK</div><h2>You walk. <em>The agent connects the dots.</em></h2><div class="compact-flow"><div><span>INPUT</span><b>Location + interests</b></div><i>→</i><div class="compact-agent"><span>CODEX SDK · ONE CONVERSATION PER WALK</span><b>Discover → select → verify</b></div><i>→</i><div><span>OUTPUT</span><b>Map, profiles & your trail</b></div></div><div class="compact-sponsors"><div><span class="sponsor-role">DEVELOPMENT WORKFLOW</span><h3>Cline</h3><p>AI-assisted development<br>of the product.</p></div><div><span class="sponsor-role">RESEARCH & EVIDENCE</span><h3>Parallel</h3><p>Responses API builds structured<br>company profiles with citations<br>and address evidence.</p></div><div><span class="sponsor-role">CONNECTED TOOLS</span><h3>Composio</h3><p>A restricted Hacker News search<br>adds public tech-community<br>discussions about each company.</p></div></div><div class="compact-bottom"><span>OpenStreetMap: nearby places & geography</span><span>Cached research · bounded budgets · isolated worker</span></div>''','light five-agent')
slide('''<div class="eyebrow">04 — BUILT. CONNECTED. WALKED.</div><h2>From an unfamiliar street<br>to <em>a useful discovery.</em></h2><div class="stats"><div><strong>35</strong><span>nearby places discovered</span></div><div><strong>5</strong><span>sourced company profiles</span></div><div><strong>5</strong><span>places in the passed-by trail</span></div></div><p class="stats-caption">Observed in one saved San Francisco walk — real providers, real research.</p><div class="close-line"><div><span class="brand closing-brand">bizroam ↗</span><p>Stay curious. There’s a company around the corner.</p></div><div class="demo"><span>TRY THE LIVE DEMO</span><a href="https://bizroam.wip.dev.furet.network">bizroam.wip.dev.furet.network ↗</a><small>Personal WIP · password-protected</small></div></div>''','light close')
