html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><title>Bizroam — Around your corner</title><style>'''+css+'''</style></head><body><main id="stage">'''+''.join(slides)+'''</main><nav class="controls" aria-label="Slide controls"><button id="prev" aria-label="Previous slide">←</button><span id="counter">1 / 5</span><button id="next" aria-label="Next slide">→</button><small>← → / SPACE · F FULLSCREEN</small></nav><script>
let current=0;const slides=[...document.querySelectorAll('.slide')];function fit(){const s=Math.min(innerWidth/1600,innerHeight/900);const stage=document.querySelector('#stage');stage.style.transform=`translate(${(innerWidth-1600*s)/2}px,${(innerHeight-900*s)/2}px) scale(${s})`;}function show(i){current=Math.max(0,Math.min(slides.length-1,i));slides.forEach((el,j)=>{el.classList.toggle('active',j===current);el.setAttribute('aria-hidden',j!==current);});document.querySelector('#counter').textContent=`${current+1} / ${slides.length}`;history.replaceState(null,'','#'+(current+1));}document.querySelector('#prev').onclick=()=>show(current-1);document.querySelector('#next').onclick=()=>show(current+1);document.addEventListener('keydown',e=>{if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1);if(e.key.toLowerCase()==='f'){if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen();}});addEventListener('resize',fit);show((Number(location.hash.slice(1))||1)-1);fit();</script></body></html>'''
